await page.getByRole('button',{name:'Закрыть уведомление'}).click();
assert.equal(await page.locator('.live-notice').count(),0);
await page.getByRole('button',{name:'Сбросить настройки'}).click();
assert.equal(await page.locator('#duration').inputValue(),'5');
assert.equal(await page.locator('#position').inputValue(),'bottom-right');
