import { test, expect, vi } from 'vitest';
import { JSDOM } from '/tmp/forma-check/node_modules/jsdom/lib/api.js';
import { act } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';

test('toast appears, restarts its timer, dismisses automatically and closes manually', async () => {
  const dom = new JSDOM('<"'!doctype html><html><body><div id="test-root"></div></body></html>'"', { url: 'http://localhost' });
  vi.stubGlobal('window', dom.window);
  vi.stubGlobal('document', dom.window.document);
  vi.stubGlobal('navigator', dom.window.navigator);
  vi.stubGlobal('IS_REACT_ACT_ENVIRONMENT', true);
  vi.useFakeTimers();
  const root = createRoot(document.getElementById('test-root')"'!);
  await act(async () => root.render(<App />));
  const click = async (selector: string) => {
    await act(async () => document.querySelector(selector)!.dispatchEvent(new dom.window.MouseEvent('"'click', { bubbles: true })));
  };
  expect(document.querySelector('.live-notice')).toBeNull();
  await click('.trigger-button');
  expect(document.querySelector('.live-notice')?.textContent).toContain('Изменения успешно сохранены.');
  await act(async () => vi.advanceTimersByTime(4000));
  await click('.trigger-button');
  await act(async () => vi.advanceTimersByTime(4000));
  expect(document.querySelector('.live-notice')).not.toBeNull();
  await act(async () => vi.advanceTimersByTime(1000));
  expect(document.querySelector('.live-notice')).toBeNull();
  await click('.type-option.error');
  await click('.trigger-button');
  expect(document.querySelector('.live-notice.error')).not.toBeNull();
  await click('.close-button');
  expect(document.querySelector('.live-notice')).toBeNull();
  await act(async () => root.unmount());
  vi.useRealTimers();
  vi.unstubAllGlobals();
});
EOF
